#!/usr/bin/env python3
"""Turn 35 Wave 58: THE SEASON PASS ECONOMICS - two paid tiers with real prices, the original full
reward list, the level-storing mechanic that powers the buy-late strategy, and the Dynamic Stars
event path. Plus the Fanzone gap formally recorded as exhausted on the open web.

Wave 58 answers the one purchase question the user will actually face: is the Season Pass worth
buying, and when. The answer now has numbers attached - a basic pass at about $4 and a premium pass
at about $13-15, a documented reward list from the pass's first season, and a level-storing mechanic
that means waiting costs you nothing on the free track.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w58')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_sp=new_ev("sportsdunia 'How to Get Gems in DLS 2026' (31 Dec 2025, pass and gem pricing in INR), sportsdunia 'How to Get Coins in DLS 2026' (30 Dec 2025, same pricing), gamescenter.pe product page (Premium Season Pass 14.60 USD, 400 gems 11.40 USD, 2700 gems 57.90 USD), Apple App Store DLS26 IAP list (Season Pass 3.99 USD), FTG support 4404070913169 (full text re-surfaced), r/DreamLeagueSoccer jwes7t (18 Nov 2020, the original Season Pass review with the full reward list), 1dgc8zy (15 Jun 2024, premium vs basic review), 1bl405h (22 Mar 2024), 1ercjvd (13 Aug 2024, the 12-hour unlock rule), 1pcdhg8 (2 Dec 2025, new stadium designs and DP boosts), sakibpro.com/dls-26-new-update-events-players (20 Aug 2026, Season Pass Players), sportsdunia Dynamic Stars event guide (10 Jun 2026), Bluestacks DLS26 free-rewards guide",
    "THE SEASON PASS ECONOMICS - the one purchase decision, now priced. TWO PAID TIERS EXIST: a BASIC Season Pass and a PREMIUM one. Prices: the App Store lists the Season Pass at **$3.99**; sportsdunia gives **INR 399 for the basic pass and INR 1,199 for the premium**; and a Peruvian storefront lists the **Premium Season Pass at $14.60** (with 400 gems at $11.40 and 2,700 gems at $57.90). So the basic pass is about **$4** and the premium about **$13-15** - a 3-4x step up. Gem pricing for reference (INR): 90 gems 199, 400 gems 799, 910 gems 1,799, 2,700 gems 4,999, 6,000 gems 9,900. THE ORIGINAL SEASON PASS REWARD LIST (r/DLS jwes7t, Nov 2020, the pass's first season): 'what you gained with the purchase was: 4000 coins, 150 crystals, 5 legendary form boosts, 3 legendary coaches (1 technical, 1 fitness, 1 GK), 1 legendary physio, 1 legendary scout, 1 legendary agent' - which the reviewer priced at shop equivalent of '3500 coins + 500 free (GBP 6.99) + 100 gems (GBP 1.99) + 2 coach packs (GBP 7.98) + 1 transfer pack (GBP 4.99) = GBP 21.95 total'. The same review establishes the KEY MECHANIC FOR THE BUY-LATE STRATEGY: 'You get to advance a SP level every 10 hours. If you don't play every 10 hours, the game will STORE the level so that you can advance multiple levels at once on a later time if you want to' - and 'advancing a level usually takes 3 matches, depending on your performance. Online and league matches give the most SP experience.' So the free track's drip-feed is a STORAGE system, not a punishment for inactivity: levels bank. THE OFFICIAL RULES (re-surfaced in full, applicable from version 12200 onwards): two tiers FREE and SEASON PASS; purchasing unlocks the Progress Bank; the Premium pass 'will turn some elements of your game profile gold'; it is not a subscription and must be repurchased each season; Season Points come from matches with the amount varying by mode; buying instantly unlocks Premium content for free tiers already unlocked; tier locks correspond to the current day; and the Premium pass removes all tier locks. WHAT THE PREMIUM TIER ACTUALLY ADDS (r/DLS 1dgc8zy, Jun 2024): 'you get tiers unlocked and completed up until Tier 8, where you then have to wait to complete the others. You also get DOUBLE the Season Pass points (SP) and Live XP points (XP). SP helps complete the season pass faster and XP helps fill up your progress bank faster and takes you up the leaderboard faster too.' A second reviewer is blunter: 'the premium season pass and the lower tier one are almost the exact same. The only difference is that the premium season pass allows you to also gain XP throughout the season which allows you to gain better rewards in Dream League Live leaderboard. Also... you can get a head start in the season tiers.' The packs differ too: 'in the scout/transfer pack you get a legendary agent and 3 legendary scouts and a couple rare scouts... the agent pack is more expensive, I only get 1 agent if each rarity.' The verdict from the original review still stands: 'the paid season pass is most suitable for a NEW player but not so much for a veteran player who's maxed out a lot of stuff', and 'regardless if you decide to pay or not, you gain 1095 coins and an epic agent completely for free.' THE FANZONE GAP IS NOW EXHAUSTED ON THE OPEN WEB: three further targeted searches across wave 58 returned only the official function copy ('Clan bonuses and Stadium discounts'), the Summer Spotlight launch note, and one mod-site claim of five levels - no per-level costs, no level count from any reliable source, no bonus values. THE DYNAMIC STARS EVENT PATH (sportsdunia, Jun 2026): every base card starts at **82 OVR** and 'only one of them will be upgraded to **96 OVR**', via a round-by-round ladder - +1 OVR per Group Stage win, +2 for the Round of 32, +2 for the Round of 16, +2 for the quarter-finals, +2 for the semi-finals, and 96 OVR for the final winner - across an event running 8 June to 20 July 2026, with 3 Dynamic Agents on the premium pass and 2 free. SEASON PASS PLAYERS: a new card type announced alongside Cult Heroes, with agents and players on BOTH the free and premium tracks, and 6 exclusive Season Pass cards planned with the roster unrevealed.",
    "evidence/raw/turn35_w58/EV-472_season_pass_economics.html",
    "SEASON PASS ECONOMICS: TWO paid tiers - basic at about $4 (INR 399) and premium at about $13-15 (INR 1,199 / $14.60). THE ORIGINAL REWARD LIST (first season): 4,000 coins, 150 crystals, 5 legendary form boosts, 3 legendary coaches (1 technical, 1 fitness, 1 GK), 1 legendary physio, 1 legendary scout, 1 legendary agent - shop-equivalent about GBP 21.95. THE KEY MECHANIC: 'you get to advance a SP level every 10 hours. If you don't play every 10 hours, the game will STORE the level so that you can advance multiple levels at once' - so the free track's drip-feed is a STORAGE system and waiting costs nothing. WHAT PREMIUM ADDS: tiers unlocked to Tier 8 immediately, DOUBLE Season Points and DOUBLE Live XP, a gold profile trim, a head start on tiers, and better packs (a legendary agent + 3 legendary scouts in the scout/transfer pack). Reviewers' verdict: 'almost the exact same' as basic apart from the XP, and 'most suitable for a NEW player but not so much for a veteran'. Free players still get 1,095 coins and an epic agent. FANZONE GAP EXHAUSTED on the open web - only the official function copy and one mod-site claim of five levels. DYNAMIC STARS: all base cards 82 OVR, one card reaches 96 OVR via +1 per group win then +2 per knockout round",
    quality="community")

add_claim("THE SEASON PASS HAS TWO PAID TIERS: a basic pass at about $4 (INR 399) and a Premium pass at about $13-15 (INR 1,199, or $14.60 on a Peruvian storefront). The App Store lists the Season Pass at $3.99.", 2, "seasonpass/two-paid-tiers-priced", [e_sp], notes="The first real pricing picture for the one purchase the user will consider")
add_claim("THE ORIGINAL SEASON PASS REWARD LIST (first season): 4,000 coins, 150 crystals, 5 legendary form boosts, 3 legendary coaches (one technical, one fitness, one GK), 1 legendary physio, 1 legendary scout and 1 legendary agent - priced by the reviewer at about GBP 21.95 of shop-equivalent value.", 2, "seasonpass/original-reward-list", [e_sp], notes="The only complete reward list on record; current-season contents remain unpublished")
add_claim("THE FREE TRACK'S DRIP-FEED IS A STORAGE SYSTEM: 'you get to advance a SP level every 10 hours. If you don't play every 10 hours, the game will store the level so that you can advance multiple levels at once on a later time.' Waiting therefore costs nothing on the free track, and a level typically takes about 3 matches with online and league matches giving the most Season Points.", 2, "seasonpass/level-storage-mechanic", [e_sp], notes="Mechanically underpins the buy-late strategy")
add_claim("WHAT THE PREMIUM TIER ADDS: tiers unlocked and completed up to Tier 8 immediately, DOUBLE Season Points and DOUBLE Live XP, a gold profile trim, a head start on the tier ladder, and better packs (the scout/transfer pack contains a legendary agent and 3 legendary scouts, while the agent pack contains 1 agent of each rarity).", 2, "seasonpass/premium-benefits", [e_sp])
add_claim("Reviewers' verdict on the Premium pass: 'the premium season pass and the lower tier one are almost the exact same. The only difference is that the premium season pass allows you to also gain XP throughout the season which allows you to gain better rewards in Dream League Live leaderboard.' And from the original review: 'the paid season pass is most suitable for a NEW player but not so much for a veteran player who's maxed out a lot of stuff.'", 2, "seasonpass/premium-value-verdict", [e_sp])
add_claim("Free players still get 1,095 coins and an epic agent from the Season Pass without paying, and the pass must be repurchased every 10-day season because it is not a subscription.", 2, "seasonpass/free-track-value", [e_sp])
add_claim("THE FANZONE PER-LEVEL COSTS ARE EXHAUSTED ON THE OPEN WEB: three targeted searches returned only the official function copy ('Clan bonuses and Stadium discounts'), the Summer Spotlight launch note, and one mod-site claim of five levels. No per-level gem cost, level count or bonus value exists in any reliable source.", 2, "facilities/fanzone-gap-exhausted", [e_sp], notes="Documented negative on the search space itself - only device inspection can close it")
add_claim("THE DYNAMIC STARS EVENT PATH: every base card starts at 82 OVR and only one is upgraded to 96 OVR, via +1 OVR per Group Stage win then +2 OVR for each of the Round of 32, Round of 16, quarter-finals and semi-finals, with 96 OVR for the final winner. The event ran 8 June to 20 July 2026 with 3 Dynamic Agents on the premium pass and 2 free.", 2, "events/dynamic-stars-path", [e_sp])
add_claim("SEASON PASS PLAYERS are a new card type announced alongside Cult Heroes, with special agents and players on BOTH the free and premium tracks, and 6 exclusive Season Pass cards planned with the roster still unrevealed.", 2, "cards/season-pass-players", [e_sp])
add_claim("New stadium designs were added for 950 gems in the December 2025 build, alongside a 'p2w stadium', and DP boosts became a guaranteed gem purchase rather than a chance - one player spent over 600 gems on 5-6 boosts and only ever received the 50% tier.", 3, "stadium/new-designs-and-boost-change", [e_sp], notes="Corroborates the KB's boost pricing and the 'choose your boost' change")

for name in ('EV-472_season_pass_economics.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
